const S={token:'',boot:null,page:1,pages:1,selected:null,detail:null,entity:null,job:null,poll:null,comparePoll:null,compareOutput:null,contractPoll:null,serverRow:null,fieldRow:null,fieldEditor:null,view:localStorage.getItem('ptAssetCatalogView')||'table'};
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtBytes=n=>{n=Number(n||0);const u=['B','KB','MB','GB','TB'];let i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return `${n.toFixed(i?1:0)} ${u[i]}`};
const toast=m=>{const x=$('#toast');x.textContent=m;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2300)};
function bindPreviewFallbacks(root=document){root.querySelectorAll('img[data-preview-fallback]').forEach(img=>{if(img.dataset.previewBound)return;img.dataset.previewBound='1';img.addEventListener('error',()=>{const mode=img.dataset.previewFallback||'message';const span=document.createElement('span');if(mode==='icon'){span.className='ext-icon';span.textContent=img.dataset.ext||'?'}else{span.className='micro';span.textContent='Preview unavailable'}img.replaceWith(span)},{once:true})})}
async function api(path,opt={}){const o={...opt,headers:{...(opt.headers||{})}};if(o.method&&o.method!=='GET')o.headers['X-PT-UI-Token']=S.token;if(o.body&&typeof o.body!=='string'){o.headers['Content-Type']='application/json';o.body=JSON.stringify(o.body)}const r=await fetch(path,o);const d=await r.json().catch(()=>({ok:false,error:`HTTP_${r.status}`}));if(!r.ok)throw new Error(d.detail||d.error||`HTTP ${r.status}`);return d}
function setTab(name){$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.tab===name));$$('.tab').forEach(x=>x.classList.remove('active'));$(`#tab-${name}`).classList.add('active');$('#pageTitle').textContent={catalog:'Catálogo de Assets',entities:'Entidades Monster / NPC',server:'Servidor / Asset Enrichment',compare:'Comparar Árvores',jobs:'Tarefas & Console',reports:'Relatórios de Audit',docs:'Ajuda / Guias',settings:'Configurações & Integração'}[name];if(name==='entities')loadEntities();if(name==='server'){loadServer();loadContracts();}if(name==='jobs')loadJobs();if(name==='reports')loadReports()}
async function boot(){const d=await api('/api/bootstrap');S.boot=d;S.token=d.token;const tu=d.optional_capabilities?.texture_upscale||{};$('#versions').textContent=`UI ${d.ui_version} · Core ${d.backend_version}`;$('#metrics').innerHTML=`<div class=metric><b>${d.catalog.file_count.toLocaleString()}</b><span>Arquivos do client</span></div><div class=metric><b>${fmtBytes(d.catalog.total_bytes)}</b><span>Bytes indexados</span></div><div class=metric><b>${esc(d.backend_version)}</b><span>Backend</span></div><div class=metric><b>Somente leitura</b><span>Client + Server</span></div>`;$('#settingsInfo').innerHTML=`<dt>UI</dt><dd>${esc(d.ui_version)}</dd><dt>Backend</dt><dd>${esc(d.backend_version)}</dd><dt>Project</dt><dd><code>${esc(d.project_root)}</code></dd><dt>Client</dt><dd><code>${esc(d.client_root)}</code></dd><dt>Server</dt><dd><code>${esc(d.server_root||'não configurado')}</code></dd><dt>Source Summit</dt><dd><code>${esc(d.source_root||'não configurado')}</code></dd><dt>Source EU</dt><dd><code>${esc(d.reference_source_root||'não configurado')}</code></dd><dt>Contract donors</dt><dd>${Number((d.contract_donor_clients||[]).length)} read-only</dd><dt>Source writes</dt><dd>Client disabled · Server disabled · C/C++ sources disabled</dd><dt>Texture upscale</dt><dd>Lanczos ${tu.lanczos_ready?'READY':'UNAVAILABLE'} · Real-ESRGAN ${tu.realesrgan_ready?'READY':'UNAVAILABLE'}</dd>`;renderArm();if($('#compareLeft'))$('#compareLeft').value=d.client_root;if($('#serverRootInput'))$('#serverRootInput').value=d.server_root||'';if($('#sourceRootInput'))$('#sourceRootInput').value=d.source_root||'';if($('#referenceSourceRootInput'))$('#referenceSourceRootInput').value=d.reference_source_root||'';if($('#contractDonorsInput'))$('#contractDonorsInput').value=(d.contract_donor_clients||[]).join('\n');if($('#contractServerDonorsInput'))$('#contractServerDonorsInput').value=(d.contract_donor_servers||[]).join('\n');await loadCatalog()}
function renderArm(){if(!S.boot)return;const until=Number(S.boot.write_armed_until||0),a=Boolean(S.boot.write_armed)&&(!until||Date.now()/1000<until);if(S.boot.write_armed&&!a)S.boot.write_armed=false;$('#armState').textContent=a?'Workspace/build armado':'Ações de build bloqueadas';$('#armState').style.color=a?'var(--warn)':'';$('#armBtn').textContent=a?'Desarmar build':'Armar workspace/build'}
function params(){return new URLSearchParams({q:$('#search').value,category:$('#category').value,folder:$('#folder').value,role:$('#role').value,ext:$('#ext').value,favorites:$('#favorites').checked?'1':'0',page:String(S.page),page_size:'100'})}
async function loadCatalog(){const d=await api('/api/catalog?'+params());S.pages=d.pages;renderFacets(d.facets);$('#pageInfo').textContent=`Page ${d.page} / ${d.pages} · ${d.total.toLocaleString()} assets`;$('#prevPage').disabled=d.page<=1;$('#nextPage').disabled=d.page>=d.pages;$('#assetRows').innerHTML=d.items.map(r=>`<tr data-path="${esc(r.path)}" class="${S.selected===r.path?'selected':''}"><td class="star ${r.favorite?'on':''}">${r.favorite?'★':'☆'}</td><td class=path title="${esc(r.path)}">${esc(r.path)}</td><td><span class=badge>${esc(r.category)}</span></td><td title="${esc(r.folder_path||'')}">${esc(r.folder||'—')}</td><td>${esc(r.role)}</td><td title="${esc(r.extension_description||'')}">${esc(r.ext||'—')}</td><td>${fmtBytes(r.size)}</td></tr>`).join('');$$('#assetRows tr').forEach(tr=>tr.onclick=()=>selectAsset(tr.dataset.path));$('#galleryMode').innerHTML=d.items.map(r=>`<div class="asset-card ${S.selected===r.path?'selected':''}" data-card-path="${esc(r.path)}"><div class=thumb>${r.previewable?`<img loading="lazy" src="/api/preview?path=${encodeURIComponent(r.path)}" data-preview-fallback="icon" data-ext="${esc((r.ext||'?').replace('.','').toUpperCase())}">`:`<span class=ext-icon>${esc((r.ext||'?').replace('.','').toUpperCase())}</span>`}</div><div class=card-body><div class=card-name title="${esc(r.name)}">${esc(r.name)}</div><div class=card-path title="${esc(r.path)}">${esc(r.path)}</div><div class=card-tags><span class=badge>${esc(r.role)}</span><span class="star ${r.favorite?'on':''}">${r.favorite?'★':'☆'}</span></div></div></div>`).join('');$$('[data-card-path]').forEach(x=>x.onclick=()=>selectAsset(x.dataset.cardPath));bindPreviewFallbacks($('#galleryMode'));applyView()}
function applyView(){const gallery=S.view==='gallery';$('#tableMode').classList.toggle('hidden',gallery);$('#galleryMode').classList.toggle('hidden',!gallery);$('#tableView').classList.toggle('active',!gallery);$('#galleryView').classList.toggle('active',gallery)}
function fillSelect(id,arr,label,{extensions=false}={}){const el=$(id),cur=el.value;el.innerHTML=`<option value="">${label}</option>`+arr.slice(0,160).map(x=>{const blank=x.value==='';const value=blank&&extensions?'__NO_EXT__':x.value;let text=x.label||x.value;if(blank)text=extensions?'Sem extensão':'(raiz)';if(extensions&&x.description)text=`${text} — ${x.description}`;return `<option value="${esc(value)}" title="${esc(x.description||x.value||'')}">${esc(text)} (${x.count})</option>`}).join('');if([...el.options].some(o=>o.value===cur))el.value=cur;else el.value=''}
function renderFacets(f){fillSelect('#category',f.categories,'Todas as categorias');fillSelect('#folder',f.folders||[],'Todas as pastas');fillSelect('#role',f.roles,'Todos os roles');fillSelect('#ext',f.extensions,'Todas as extensões',{extensions:true})}
async function selectAsset(path){S.selected=path;await loadCatalog();const d=await api('/api/asset?path='+encodeURIComponent(path));renderDetail(d.asset)}
function renderDetail(a){if(!a)return;S.detail=a;const acts=S.boot.actions.filter(x=>a.capabilities.includes(x.key));const groups={};acts.forEach(x=>(groups[x.group]??=[]).push(x));const preview=a.previewable?`<div class=preview><img src="/api/preview?path=${encodeURIComponent(a.path)}" data-preview-fallback="message"></div>`:`<div class=preview><span class=micro>Preview não disponível para este tipo; modelos 3D usam workflows Blender quando aplicável.</span></div>`;const headMeta=a.registry_asset&&Number(a.head_candidate_count||0)?`<b>Cabeças verificadas</b><span>${Number(a.head_candidate_count)} · ${(a.head_candidates||[]).slice(0,4).map(x=>esc(x.asset)).join(', ')}${Number(a.head_candidate_count)>4?' …':''}</span>`:'';const backendMeta=a.registry_asset?`<b>Family</b><span>${esc(a.family||'—')}</span><b>Kind</b><span>${esc(a.kind||'—')}</span><b>Binding</b><span>${esc([a.binding_mode,a.binding_source].filter(Boolean).join(' / ')||'—')}</span>${headMeta}`:`<b>Registry</b><span>${a.inventory_record_present?'support record':'physical file'}</span><b>Family</b><span>${esc(a.inventory_family||'—')}</span><b>Kind</b><span>${esc(a.inventory_kind||'—')}</span>`;$('#detailPanel').innerHTML=`<div class=asset-title><h2>${esc(a.name)}</h2><span class="star ${a.favorite?'on':''}" id=detailStar>${a.favorite?'★':'☆'}</span></div><div class=asset-meta><b>Path</b><span>${esc(a.path)}</span><b>Category</b><span>${esc(a.category)}</span><b>Pasta</b><span title="${esc(a.folder_path||'')}">${esc(a.folder||'—')}</span><b>Role</b><span>${esc(a.role)}</span><b>Extensão</b><span>${esc(a.ext||'—')} · ${esc(a.extension_description||'')}</span><b>Size</b><span>${fmtBytes(a.size)}</span><b>Physical hint</b><span>${esc(a.physical_hint||'—')}</span>${backendMeta}<b>Capabilities</b><span>${a.capabilities.length}</span></div>${preview}${Object.entries(groups).map(([g,x])=>`<div class=action-group><h4>${esc(g)}</h4><div class=actions>${x.map(z=>`<button data-action="${z.key}" class="action-btn ${z.mutates_build&&!S.boot.write_armed?'locked':''}" title="${esc(z.description)}"><span>${esc(z.label)}</span><small>${esc(z.description)}</small></button>`).join('')}</div></div>`).join('')}<div class=editor><h3>Anotação do catálogo</h3><label>Override de categoria</label><input id=catOverride value="${esc(a.category===a.inferred_category?'':a.category)}" placeholder="e.g. UI, CHARACTER, MONSTER"><label>Override de role</label><input id=roleOverride value="${esc(a.role===a.inferred_role?'':a.role)}" placeholder="e.g. HEAD, ARMOR, PANEL"><label>Tags</label><input id=tags value="${esc((a.tags||[]).join(', '))}" placeholder="quest, old-ui, candidate"><label>Notas</label><textarea id=notes>${esc(a.notes||'')}</textarea><button class="btn primary" id=saveMeta>Salvar anotação</button></div>`;bindPreviewFallbacks($('#detailPanel'));$('#detailStar').onclick=()=>saveMeta({favorite:!a.favorite});$$('#detailPanel [data-action]').forEach(b=>b.onclick=()=>runAction(b.dataset.action));$('#saveMeta').onclick=()=>saveMeta({category_override:$('#catOverride').value,role_override:$('#roleOverride').value,tags:$('#tags').value,notes:$('#notes').value})}
async function saveMeta(patch){const d=await api('/api/state/update',{method:'POST',body:{path:S.selected,patch}});toast('Anotação do catálogo saved');renderDetail(d.asset);await loadCatalog()}
async function runAction(action){if(!S.selected&&action!=='doctor')return;const spec=S.boot.actions.find(x=>x.key===action);if(spec?.mutates_build&&!S.boot.write_armed){$('#modal').classList.remove('hidden');toast('Armar workspace/build actions first');return}let options={};if(action==='validate_animation'||action==='diagnose_animation'){const motion=prompt('Motion ativa (case-insensitive; ex.: STAND, stand, WALK, ATTACK)','STAND');if(!motion)return;const mq=motion.trim();options.motion=/^\d+$/.test(mq)||mq.toLowerCase()==='auto'?mq:mq.toUpperCase();const load=prompt(action==='validate_animation'?'Actions: all (recomendado; workspace persistente) ou selected (somente esta motion). core permanece como modo legado.':'Actions a carregar: selected, core ou all',action==='validate_animation'?'all':'selected');if(load===null)return;options.load_actions=(load.trim().toLowerCase()|| (action==='validate_animation'?'all':'selected'));if(action==='validate_animation'){const candidates=S.detail?.head_candidates||[],isCharacter=String(S.detail?.category||'').toUpperCase()==='CHARACTER';if(!isCharacter){options.head='none';options.head_tier='auto'}else{const hint=candidates.slice(0,5).map(x=>x.asset).join('\n');const head=prompt(`Cabeça (somente CHARACTER): auto, none ou path exato.${hint?'\nCandidatas verificadas:\n'+hint:''}`,candidates.length?'auto':'none');if(head===null)return;options.head=head.trim()||'auto';if(options.head.toLowerCase()!=='none'){const tier=prompt('Tier da cabeça: auto, base, a, b, c, d ou t','auto');if(tier===null)return;options.head_tier=tier.trim()||'auto'}}}}if(action==='import_blender'){const infos=S.detail?.model_info_options||[];const lod=prompt('LOD do import: auto, high, default ou low','auto');if(lod===null)return;options.lod=lod.trim().toLowerCase()||'auto';const load=prompt('Animações no workspace: all (todas), selected (somente a escolhida) ou none','all');if(load===null)return;options.load_actions=load.trim().toLowerCase()||'all';if(!['all','selected','none'].includes(options.load_actions)){toast('Use all, selected ou none');return}if(options.load_actions!=='none'){const motion=prompt('Motion inicial (case-insensitive; ex.: STAND, WALK, ATTACK)','STAND');if(motion===null)return;options.motion=motion.trim()||'STAND'}const openMode=prompt('Abrir qual workspace? paint = editar/pintar estável; animation = preview com Actions','paint');if(openMode===null)return;options.open_mode=openMode.trim().toLowerCase()||'paint';if(!['paint','animation'].includes(options.open_mode)){toast('Use paint ou animation');return}if(infos.length>1){const choices=infos.map(x=>`${x.inx}  [${(x.available_lods||[]).join(', ')||'sem LOD'}]`).join('\n');const mi=prompt(`Este asset possui múltiplos INX/model-info. Escolha o path exato:\n${choices}`,infos[0].inx);if(mi===null)return;options.model_info=mi.trim()}else if(infos.length===1){options.model_info=infos[0].inx}}if(action==='upscale_texture'){const scale=prompt('Escala: 2, 3 ou 4','4');if(scale===null)return;options.scale=scale.trim();if(!['2','3','4'].includes(options.scale)){toast('Use escala 2, 3 ou 4');return}const backend=prompt('Backend: lanczos (local) ou realesrgan (AI/Vulkan)','lanczos');if(backend===null)return;options.backend=backend.trim().toLowerCase()||'lanczos';if(!['lanczos','realesrgan'].includes(options.backend)){toast('Use lanczos ou realesrgan');return}const risk=/(^|\/)(ui|interface|interfaces|login|startimage|clanimage|font|fonts|cursor|cursors)(\/|$)|\/sinimage\/(help|messagebox|chipbutton)\//i.test(String(S.selected||''));if(risk){if(!confirm('Este path parece UI/atlas e pode usar recortes em pixels. Fazer upscale mesmo assim?'))return;options.include_ui=true}}if(action==='paint_stage072'){const stage=prompt('Stage TexLink (0–7)','0');if(stage===null)return;options.stage=stage}try{const d=await api('/api/action',{method:'POST',body:{action,path:action==='doctor'?null:S.selected,options}});S.job=d.job.id;toast(spec?.interactive?'Validação iniciada; acompanhe o console e responda quando solicitado':'Tarefa iniciada');showJob(d.job.id)}catch(e){console.error(e);toast(e.message)}}
async function showJob(id){S.job=id;clearInterval(S.poll);const poll=async()=>{try{const d=await api('/api/job?id='+encodeURIComponent(id));const j=d.job,active=['QUEUED','RUNNING','CANCELLING'].includes(j.status),waiting=Boolean(j.awaiting_input);$('#consoleStatus').textContent=`${j.action} · ${j.status}${j.interactive?' · avaliação humana':''}`;$('#console').textContent=j.tail||j.command_display;$('#console').scrollTop=$('#console').scrollHeight;$('#cancelJobBtn').style.display=active?'inline-block':'none';$('#cancelJobBtn').disabled=j.status==='CANCELLING';$('#jobInput').classList.toggle('hidden',!waiting);const inputLabel=$('#jobInput span');if(inputLabel)inputLabel.textContent=waiting?(j.input_prompt?`Avaliação solicitada: ${j.input_prompt}`:'O validator está aguardando sua avaliação:'):'O validator está aguardando sua avaliação:';if(['PASS','FAIL','ERROR','CANCELLED'].includes(j.status)){clearInterval(S.poll);$('#jobInput').classList.add('hidden')}}catch(e){}};await poll();S.poll=setInterval(poll,700)}
async function sendJobInput(value){if(!S.job)return;try{await api('/api/job/input',{method:'POST',body:{id:S.job,value}});toast('Resposta enviada ao validator');$('#jobInput').classList.add('hidden');showJob(S.job)}catch(e){toast(e.message)}}
async function cancelCurrentJob(){if(!S.job)return;try{await api('/api/job/cancel',{method:'POST',body:{id:S.job}});toast('Cancelamento solicitado');showJob(S.job)}catch(e){toast(e.message)}}
async function loadJobs(){const d=await api('/api/jobs');$('#jobsList').innerHTML=d.jobs.length?d.jobs.map(j=>`<div class=job><div><span class="status ${esc(j.status)}">${esc(j.status)}</span><small>${new Date(j.created_at*1000).toLocaleString()}</small></div><div><b>${esc(j.action)}</b><small>${esc(j.asset||'system')}</small><code>${esc(j.command_display)}</code></div><button class="btn small" data-job="${j.id}">Console</button></div>`).join(''):'<div class=empty>Nenhuma tarefa ainda.</div>';$$('[data-job]').forEach(b=>b.onclick=()=>{setTab('catalog');showJob(b.dataset.job)})}
async function loadReports(){const d=await api('/api/reports');$('#reportsList').innerHTML=d.reports.length?d.reports.map(r=>`<div class=report><div><span class="status ${esc(r.status||'')}">${esc(r.status||'REPORT')}</span><small>${new Date(r.mtime*1000).toLocaleString()}</small></div><div><b>${esc(r.name)}</b><small>${esc(r.format||'JSON')} ${r.release_version?'· '+esc(r.release_version):''}</small></div><span>${fmtBytes(r.size)}</span></div>`).join(''):'<div class=empty>Nenhum relatório JSON encontrado em pt_build.</div>'}
function entityCountsText(e){const rc=e.role_counts||{};return [rc.MODEL?`${rc.MODEL} model`:null,rc.CONFIG?`${rc.CONFIG} config`:null,rc.ANIMATION?`${rc.ANIMATION} anim`:null,rc.TEXTURE?`${rc.TEXTURE} tex`:null,e.registry_asset_count?`${e.registry_asset_count} registry`:null,e.animation_binding_ready_count?`${e.animation_binding_ready_count} anim-ready`:null].filter(Boolean).join(' · ')}
async function openEntityFolder(group,folder){$('#category').value=group;S.page=1;await loadCatalog();$('#folder').value=folder;await loadCatalog();setTab('catalog')}
function renderEntityDetail(d){const e=d.entity;if(!e)return;const preview=e.representative_preview?`<img src="/api/preview?path=${encodeURIComponent(e.representative_preview)}" data-preview-fallback="icon" data-ext="${esc(e.semantic_group==='MONSTER'?'MON':'NPC')}">`:`<span class=ext-icon>${esc(e.semantic_group==='MONSTER'?'MON':'NPC')}</span>`;const fam=Object.entries(e.registry_family_counts||{}).map(([k,v])=>`${k} (${v})`).join(', ')||'—';const bind=Object.entries(e.registry_binding_mode_counts||{}).map(([k,v])=>`${k} (${v})`).join(', ')||'—';const models=(e.registry_assets||[]).filter(x=>x.kind==='SMD_MODEL_062'||String(x.family||'').startsWith('SMD_'));const modelHtml=models.length?models.map(x=>`<div class=entity-model-row><b>${esc(x.path||'')}</b><small>${esc(x.family||'—')} · ${esc(x.binding_mode||'NONE')} / ${esc(x.binding_source||'NONE')}</small><small>binding ${x.rigid_binding_ready?'ready':'não'} · animação ${x.animation_binding_ready?'ready':'não'}</small></div>`).join(''):'<div class=micro>Nenhum modelo semântico do registry associado a esta pasta.</div>';$('#entityDetail').innerHTML=`<div class=entity-detail-grid><div><div class=entity-detail-preview>${preview}</div><div style="margin-top:10px"><button class="btn primary" id=openEntityFolder>Abrir pasta no Catálogo</button></div></div><div><h2 style="margin-top:0">${esc(e.display_name)}</h2><div class=entity-detail-meta><b>Grupo</b><span>${esc(e.semantic_group)}</span><b>Pasta</b><span>${esc(e.folder_root)}</span><b>Arquivos físicos</b><span>${Number(e.asset_count||0).toLocaleString()}</span><b>Registry</b><span>${Number(e.registry_asset_count||0).toLocaleString()} assets</span><b>Famílias</b><span>${esc(fam)}</span><b>Bindings</b><span>${esc(bind)}</span><b>Rigid ready</b><span>${e.rigid_binding_ready_count||0}</span><b>Animação ready</b><span>${e.animation_binding_ready_count||0}</span><b>Runtime</b><span>${esc(e.runtime_status)}</span><b>Writer</b><span>${esc(e.writer_status)}</span></div><div class=entity-path-list><h3>Modelos / contexto do registry</h3>${modelHtml}</div></div></div>`;bindPreviewFallbacks($('#entityDetail'));$('#openEntityFolder').onclick=()=>openEntityFolder(e.semantic_group,e.folder_root)}
async function selectEntity(key){S.entity=key;$$('[data-entity-key]').forEach(x=>x.classList.toggle('selected',x.dataset.entityKey===key));try{const d=await api('/api/entity?key='+encodeURIComponent(key));renderEntityDetail(d)}catch(e){$('#entityDetail').innerHTML=`<div class=empty>${esc(e.message)}</div>`}}
async function loadEntities(){const group=$('#entityGroup')?.value||'',q=$('#entitySearch')?.value.trim()||'';try{const d=await api(`/api/entities?group=${encodeURIComponent(group)}&q=${encodeURIComponent(q)}&limit=1000`);$('#entitySummary').textContent=`${Number(d.live_entity_count||0).toLocaleString()} entidades no client · ${Number(d.known_seed_entity_count||0).toLocaleString()} conhecidas no corpus`;$('#entityGrid').innerHTML=d.items.length?d.items.map(e=>{const preview=e.representative_preview?`<img loading="lazy" src="/api/preview?path=${encodeURIComponent(e.representative_preview)}" data-preview-fallback="icon" data-ext="${esc(e.semantic_group==='MONSTER'?'MON':'NPC')}">`:`<span class=ext-icon>${esc(e.semantic_group==='MONSTER'?'MON':'NPC')}</span>`;return `<div class="asset-card entity-card ${S.entity===e.entity_key?'selected':''}" data-entity-key="${esc(e.entity_key)}"><div class=thumb>${preview}</div><div class=card-body><div class=card-name title="${esc(e.display_name)}">${esc(e.display_name)}</div><div class=card-path title="${esc(e.folder_root)}">${esc(e.folder_root)}</div><div class=entity-stats>${esc(entityCountsText(e)||`${e.asset_count} assets`)}</div><div class=card-tags><span class=badge>${esc(e.semantic_group)}</span><span class=badge>${e.known_canonical_entity?'KNOWN':'LIVE'}</span>${e.rigid_binding_ready_count?`<span class=badge>BIND ${e.rigid_binding_ready_count}</span>`:''}</div></div></div>`}).join(''):'<div class=empty>Nenhuma entidade encontrada com estes filtros.</div>';bindPreviewFallbacks($('#entityGrid'));$$('[data-entity-key]').forEach(x=>x.onclick=()=>selectEntity(x.dataset.entityKey));if(S.entity&&d.items.some(e=>e.entity_key===S.entity))await selectEntity(S.entity)}catch(e){$('#entityGrid').innerHTML=`<div class=empty>${esc(e.message)}</div>`}}
function serverMetric(label,value){return `<div class=metric><b>${value==null?'—':esc(value)}</b><span>${esc(label)}</span></div>`}
function summaryPairs(obj,pairs){return `<div class=server-summary-grid>${pairs.map(([k,label,fmt])=>`<b>${esc(label)}</b><span>${fmt?fmt(obj?.[k]):esc(obj?.[k]??'—')}</span>`).join('')}</div>`}
function reportState(x){return x?.status||'SEM RELATÓRIO'}
const serverReasonHelp={
ZHOON_REFERENCE_MISSING:'A definição aponta para um recurso de nome/chat que não foi encontrado. O visual pode existir, mas o bundle server-side não fecha.',
MODEL_INX_NOT_RESOLVED_CLIENT_OR_SERVER:'O model lógico não encontrou um INX correspondente no client nem no server.',
SPC_NOT_PRESENT:'Este field não possui SPC. Isso pode ser legítimo se não houver NPC fixo; permanece parcial até o uso runtime estar entendido.',
SPM_NOT_PRESENT:'Este field não possui tabela SPM de spawn. Pode ser legítimo, mas o bundle não está completo para spawn data-driven.',
AMBIGUOUS_STAGE_BASENAME:'Mais de um stage SMD usa o mesmo basename; o tool não escolhe automaticamente entre eles.',
CODE_NOT_PARSED:'O OpenItem não forneceu uma identidade segura pelo parser/filename conhecido.',
DUPLICATE_CODE:'Mais de uma definição server-side usa o mesmo item code; precisa de revisão semântica antes de qualquer migração.',
};
function statusClass(v){v=String(v||'').toUpperCase();if(v.includes('PASS')||v.includes('RESOLVED'))return'pass';if(v.includes('BLOCK'))return'blocked';return'review'}
function setCountOptions(el,counts,label){const cur=el.value;el.innerHTML=`<option value="">${esc(label)}</option>`+Object.entries(counts||{}).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<option value="${esc(k)}">${esc(k)} (${Number(v).toLocaleString()})</option>`).join('');if([...el.options].some(o=>o.value===cur))el.value=cur}
function serverRowIdentity(kind,row){if(kind==='entities')return row.definition||row.model_reference||'Entidade';if(kind==='fields')return row.basename||row.selected_stage||'Field';return row.definition||row.code||'OpenItem'}
function serverRowLink(kind,row){if(kind==='entities')return row.logical_inx||row.model_reference||'—';if(kind==='fields')return row.selected_stage||(row.stage_candidates||[]).join(' | ')||'—';return row.code||'—'}
function renderServerRowDetail(kind,row){const reasons=(row.reasons||[]);const reasonHtml=reasons.length?reasons.map(r=>`<div class=chain-row><b>${esc(r)}</b><span>${esc(serverReasonHelp[r]||'Este motivo mantém o bundle fora de automação até o contrato correspondente estar provado.')}</span></div>`).join(''):'<div class=chain-row><b>Sem blocker registrado</b><span>O gate atual não reportou dependência obrigatória ausente.</span></div>';let chain='';if(kind==='entities'){chain=`<div class=chain-row><b>Definição server</b><code>${esc(row.definition||'—')}</code></div><div class=chain-row><b>Model lógico</b><code>${esc(row.model_reference||'—')}</code></div><div class=chain-row><b>INX</b><code>${esc(row.logical_inx||'—')}</code><small>server ${row.server_inx_exists?'✓':'—'} · client ${row.client_inx_exists?'✓':'—'}</small></div><div class=chain-row><b>ZHOON</b><span>${(row.zhoon||[]).map(z=>`${z.exists_server?'✓':'✕'} ${esc(z.reference)}`).join('<br>')||'—'}</span></div>`}else if(kind==='fields'){chain=`<div class=chain-row><b>Field</b><code>${esc(row.basename||'—')}</code></div><div class=chain-row><b>Stage</b><code>${esc(row.selected_stage||'não selecionado')}</code><small>${esc(row.stage_selection_basis||'')}</small></div><div class=chain-row><b>SPP</b><code>${esc(row.spp||'—')}</code><small>${esc(row.spp_layout||'')}</small></div><div class=chain-row><b>SPC</b><code>${esc(row.spc||'—')}</code><small>${esc(row.spc_layout||'')}</small></div><div class=chain-row><b>SPM</b><code>${esc(row.spm||'—')}</code></div>`}else{chain=`<div class=chain-row><b>Definição OpenItem</b><code>${esc(row.definition||'—')}</code></div><div class=chain-row><b>Item code</b><code>${esc(row.code||'—')}</code><small>${esc(row.identity_basis||'')}</small></div><div class=chain-row><b>ZHOON</b><span>${(row.zhoon||[]).map(z=>`${z.exists_server?'✓':'✕'} ${esc(z.reference)}`).join('<br>')||'—'}</span></div><div class=chain-row><b>Importante</b><span>O item code é identidade server-side. Ele não é, por si só, o filename do modelo ou do ícone no client.</span></div>`}$('#serverExplorerDetail').innerHTML=`<h3>${esc(serverRowIdentity(kind,row))}</h3><span class="status-chip ${statusClass(row.status)}">${esc(row.status||'REVIEW')}</span><div class=chain>${chain}</div><h4>Por que este estado?</h4><div class=chain>${reasonHtml}</div><p class=micro>Esta vista é explicativa e read-only. Para SMD/SMB/INX, a autoridade continua sendo o pipeline físico do PT Asset Tool.</p>`}
function setFieldEditorRow(kind,row){const active=kind==='fields'&&row;S.fieldRow=active?row:null;S.fieldEditor=null;const paths=active?{SPM:row.spm,SPP:row.spp,SPC:row.spc}:{SPM:null,SPP:null,SPC:null};[['#fieldOpenSpm','SPM'],['#fieldOpenSpp','SPP'],['#fieldOpenSpc','SPC']].forEach(([id,t])=>{const b=$(id);if(b)b.disabled=!paths[t]});if($('#fieldEditorState'))$('#fieldEditorState').textContent=active?`Field ${row.basename||'selecionado'} · staging only`:'Selecione um Field no explorador.';if($('#fieldEditorPath'))$('#fieldEditorPath').textContent=active?[row.spm,row.spp,row.spc].filter(Boolean).join(' · ')||'Sem companions':'—';if($('#fieldEditorSummary'))$('#fieldEditorSummary').innerHTML=active?`<div class=server-summary-grid><b>SPM</b><span>${esc(row.spm||'ausente')}</span><b>SPP</b><span>${esc(row.spp||'ausente')} · ${esc(row.spp_layout||'')}</span><b>SPC</b><span>${esc(row.spc||'ausente')} · ${esc(row.spc_layout||'')}</span><b>Política</b><span>SPM/SPP staging estruturado; SPC clone-patch somente</span></div>`:'<div class=empty>Escolha <strong>Fields</strong> no explorador e selecione um bundle.</div>';if($('#fieldEditorForm')){$('#fieldEditorForm').classList.add('hidden');$('#fieldEditorForm').innerHTML=''}}
function fieldPathFor(type){if(!S.fieldRow)return null;return S.fieldRow[String(type).toLowerCase()]||null}
function fieldSummaryPairs(f){const d=f.detail||{};if(f.type==='SPM')return `<div class=server-summary-grid><b>Path</b><span>${esc(f.relative_path)}</span><b>SHA-256</b><span><code>${esc(f.source_sha256)}</code></span><b>Encoding</b><span>${esc(d.encoding||'—')}</span><b>Atores</b><span>${Number((d.actors||[]).length)}</span><b>Draft</b><span>${esc(f.latest_draft_manifest||'nenhum')}</span></div>`;if(f.type==='SPP')return `<div class=server-summary-grid><b>Path</b><span>${esc(f.relative_path)}</span><b>SHA-256</b><span><code>${esc(f.source_sha256)}</code></span><b>Layout</b><span>${Number(d.record_count||0)} records · ${Number(d.active_count||0)} ativos</span><b>Autoria</b><span>${esc(d.authoring||'—')}</span><b>Draft</b><span>${esc(f.latest_draft_manifest||'nenhum')}</span></div>`;return `<div class=server-summary-grid><b>Path</b><span>${esc(f.relative_path)}</span><b>SHA-256</b><span><code>${esc(f.source_sha256)}</code></span><b>Layout</b><span>${Number(d.record_count||0)} records · ${Number(d.runtime_active_count||0)} ativos · ${Number(d.blank_slot_count||0)} slots blank</span><b>Autoria</b><span>${esc(d.authoring||'—')}</span><b>Sintético do zero</b><span>${esc(d.synthetic_from_zero_authoring||'BLOCKED')}</span></div>`}
function renderFieldEditor(f){S.fieldEditor=f;$('#fieldEditorState').textContent=`${f.type} · ${f.status}`;$('#fieldEditorPath').textContent=f.relative_path;$('#fieldEditorSummary').innerHTML=fieldSummaryPairs(f);const form=$('#fieldEditorForm');form.classList.remove('hidden');const d=f.detail||{};if(f.type==='SPM'){form.innerHTML=`<div class=field-editor-warning>SPM é texto legacy. O draft preserva o encoding e o estilo de newline detectados; valide o spawn no runtime antes de qualquer promoção.</div><label>Conteúdo SPM<textarea id=fieldSpmText>${esc(d.text||'')}</textarea></label><button id=fieldStageBtn class="btn primary">Criar draft SPM em pt_build</button>`}else if(f.type==='SPP'){const active=(d.records||[]).filter(r=>r.active).slice(0,30);form.innerHTML=`<div class=field-editor-warning>SPP canónico = 200 registos × 12 bytes. Esta UI altera um registo por draft e mantém tamanho/ordem.</div><div class=field-editor-records><table><thead><tr><th>#</th><th>State</th><th>X</th><th>Z</th></tr></thead><tbody>${active.map(r=>`<tr><td>${r.index}</td><td>${r.state}</td><td>${r.x}</td><td>${r.z}</td></tr>`).join('')||'<tr><td colspan=4>Nenhum start point ativo.</td></tr>'}</tbody></table></div><div class=field-editor-record-grid><label>Índice<input id=fieldSppIndex type=number min=0 max=199 value=0></label><label>State<input id=fieldSppState type=number value=1></label><label>X<input id=fieldSppX type=number value=0></label><label>Z<input id=fieldSppZ type=number value=0></label></div><button id=fieldStageBtn class="btn primary">Criar draft SPP em pt_build</button>`}else{const records=d.records||[],active=records.filter(r=>r.runtime_active),template=active.find(r=>r.standard_add_npc_code),blank=records.find(r=>r.blank);form.innerHTML=`<div class=field-editor-warning>SPC: somente clone de um record ADD_NPC conhecido. Placement de merchant vive aqui; comportamento/shop continua na definição server NPC. Campos desconhecidos de smCHAR_INFO não são inventados.</div><div class=field-editor-records><table><thead><tr><th>#</th><th>Name</th><th>Server NPC</th><th>X</th><th>Y</th><th>Z</th></tr></thead><tbody>${active.slice(0,40).map(r=>`<tr><td>${r.index}</td><td>${esc(r.name)}</td><td>${esc(r.server_npc)}</td><td>${r.x}</td><td>${r.y}</td><td>${r.z}</td></tr>`).join('')||'<tr><td colspan=6>Nenhum record ativo.</td></tr>'}</tbody></table></div><div class=field-editor-record-grid><label>Template ADD_NPC<input id=fieldSpcTemplate type=number min=0 max=99 value="${template?template.index:''}"></label><label>Slot destino<input id=fieldSpcSlot type=number min=0 max=99 value="${blank?blank.index:''}"></label><label>Nome record<input id=fieldSpcName value="NEW_NPC"></label><label>Model INI<input id=fieldSpcModel placeholder="char/npc/...ini"></label><label>Server NPC<input id=fieldSpcNpc placeholder="GameServer/NPC/...npc"></label><label>X<input id=fieldSpcX type=number value=0></label><label>Y<input id=fieldSpcY type=number value=0></label><label>Z<input id=fieldSpcZ type=number value=0></label><label>AX<input id=fieldSpcAx type=number value=0></label><label>AY<input id=fieldSpcAy type=number value=0></label><label>AZ<input id=fieldSpcAz type=number value=0></label><label>State<input id=fieldSpcState type=number value=0></label></div><button id=fieldStageBtn class="btn primary">Criar draft SPC clone em pt_build</button>`}$('#fieldStageBtn').onclick=stageFieldEditor}
async function openFieldEditor(type){const path=fieldPathFor(type);if(!path){toast(`${type} ausente neste Field`);return}try{const d=await api('/api/server/field-editor?path='+encodeURIComponent(path));renderFieldEditor(d.field)}catch(e){toast(e.message)}}
async function stageFieldEditor(){const f=S.fieldEditor;if(!f)return;if(!S.boot.write_armed){toast('Arme workspace/build antes de criar o draft');return}const body={path:f.relative_path,type:f.type,expected_sha256:f.source_sha256};if(f.type==='SPM'){body.text=$('#fieldSpmText').value}else if(f.type==='SPP'){body.edits=[{index:Number($('#fieldSppIndex').value),state:Number($('#fieldSppState').value),x:Number($('#fieldSppX').value),z:Number($('#fieldSppZ').value)}]}else{Object.assign(body,{template_index:$('#fieldSpcTemplate').value,slot_index:$('#fieldSpcSlot').value,record_name:$('#fieldSpcName').value,model_ini:$('#fieldSpcModel').value,server_npc:$('#fieldSpcNpc').value,x:Number($('#fieldSpcX').value),y:Number($('#fieldSpcY').value),z:Number($('#fieldSpcZ').value),ax:Number($('#fieldSpcAx').value),ay:Number($('#fieldSpcAy').value),az:Number($('#fieldSpcAz').value),state:Number($('#fieldSpcState').value)})}try{const d=await api('/api/server/field-editor/stage',{method:'POST',body});toast(`Draft ${f.type} criado em pt_build`);$('#fieldEditorState').textContent=`${f.type} · DRAFT PASS`;$('#fieldEditorSummary').innerHTML+=`<div class=server-summary-grid><b>Draft</b><span>${esc(d.draft.draft)}</span><b>Manifest</b><span>${esc(d.draft.manifest)}</span><b>Source write</b><span>disabled</span></div>`}catch(e){toast(e.message)}}
async function loadServerRows(){const kind=$('#serverExplorerKind')?.value||'entities',q=$('#serverExplorerSearch')?.value.trim()||'',status=$('#serverExplorerStatus')?.value||'',reason=$('#serverExplorerReason')?.value||'';try{const qs=new URLSearchParams({kind,q,status,reason,limit:'250'});const d=await api('/api/server/report?'+qs);setCountOptions($('#serverExplorerStatus'),d.status_counts,'Todos os estados');setCountOptions($('#serverExplorerReason'),d.reason_counts,'Todos os motivos');$('#serverExplorerCount').textContent=d.status==='NO_REPORT'?'Sem relatório. Execute Analisar Asset Enrichment.':`${Number(d.filtered_rows||0).toLocaleString()} de ${Number(d.total_rows||0).toLocaleString()} bundles`;const rows=d.rows||[];$('#serverExplorerRows').innerHTML=rows.length?rows.map((row,i)=>`<tr data-server-row="${i}"><td><span class="status-chip ${statusClass(row.status)}">${esc(row.status||'REVIEW')}</span></td><td>${esc(kind==='entities'?(row.kind||'ENTITY'):kind==='fields'?'FIELD':'ITEM')}</td><td class=path>${esc(serverRowIdentity(kind,row))}</td><td class=path>${esc(serverRowLink(kind,row))}</td><td>${(row.reasons||[]).slice(0,2).map(x=>`<span class=reason-chip>${esc(x)}</span>`).join('')||'—'}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">Nenhum bundle corresponde aos filtros atuais.</td></tr>';$$('[data-server-row]').forEach(tr=>tr.onclick=()=>{$$('[data-server-row]').forEach(x=>x.classList.remove('selected'));tr.classList.add('selected');const row=rows[Number(tr.dataset.serverRow)];S.serverRow=row;renderServerRowDetail(kind,row);setFieldEditorRow(kind,row)});if(rows.length){renderServerRowDetail(kind,rows[0]);setFieldEditorRow(kind,rows[0])}else{$('#serverExplorerDetail').innerHTML='<div class=empty>Nenhuma linha para detalhar.</div>';setFieldEditorRow(kind,null)}}catch(e){$('#serverExplorerRows').innerHTML=`<tr><td colspan="5" class="empty">${esc(e.message)}</td></tr>`;$('#serverExplorerCount').textContent='Erro ao carregar bundles'}}
async function loadServer(){try{const d=await api('/api/server');const root=d.server_root||'';$('#serverRootInput').value=root;$('#serverRootStatus').textContent=d.server_root_exists?'READY · read-only':'Raiz não configurada';const inv=d.reports?.inventory,design=d.reports?.design,integration=d.reports?.integration,release1=d.reports?.release1,vendorPlan=d.reports?.vendor_plan,vendorGraph=d.reports?.vendor_graph,ent=d.reports?.entities,fields=d.reports?.fields,items=d.reports?.items;$('#serverMetrics').innerHTML=[serverMetric('Server root',d.server_root_exists?'READY':'N/A'),serverMetric('Arquivos server',inv?.total_files==null?'—':Number(inv.total_files).toLocaleString()),serverMetric('Assets candidatos',inv?.asset_candidate_files==null?'—':Number(inv.asset_candidate_files).toLocaleString()),serverMetric('Excluídos/estado',inv?.hard_excluded_files==null?'—':Number(inv.hard_excluded_files).toLocaleString()),serverMetric('Asset Enrichment',d.asset_enrichment_tool?.present?String(d.asset_enrichment_tool.version||'presente').toUpperCase():'N/A')].join('');$('#serverBundleModel').innerHTML=(d.bundle_model||[]).map((x,i)=>`<div class=server-list-row><b>${i+1}</b><span>${esc(x)}</span></div>`).join('');$('#serverLifecycle').innerHTML=(d.lifecycle_policy||[]).map(x=>`<div class=server-list-row><span><b>${esc(x.ui)}</b><small>${esc(x.lifecycle)}</small></span><code>${esc(x.policy)}</code></div>`).join('');$('#serverIntegrationState').textContent=reportState(integration);$('#serverIntegrationSummary').innerHTML=summaryPairs(integration,[['integration_regression_ready','Integração pronta',v=>v?'SIM':'NÃO'],['required_failures','Falhas',v=>(v||[]).length],['next_gate','Próximo gate']]);$('#serverEntitiesState').textContent=reportState(ent);$('#serverEntitiesSummary').innerHTML=summaryPairs(ent,[['definition_count','Definições'],['resolved_visual_entry_count','Visual resolvido'],['unresolved_count','Bloqueadas/review']]);$('#serverFieldsState').textContent=reportState(fields);$('#serverFieldsSummary').innerHTML=summaryPairs(fields,[['field_bundle_count','Bundles'],['resolved_count','Resolvidos'],['unresolved_count','Review/partial']]);$('#serverItemsState').textContent=reportState(items);$('#serverItemsSummary').innerHTML=summaryPairs(items,[['item_definition_count','OpenItem'],['identity_parsed_count','Identidade lida'],['review_count','Review'],['duplicate_code_count','Códigos duplicados']]);$('#serverInventoryState').textContent=reportState(inv);$('#serverInventorySummary').innerHTML=summaryPairs(inv,[['total_files','Arquivos',v=>Number(v||0).toLocaleString()],['total_bytes','Tamanho',fmtBytes],['asset_candidate_files','Assets candidatos',v=>Number(v||0).toLocaleString()],['hard_excluded_files','Estado/log excluído',v=>Number(v||0).toLocaleString()]]);$('#release1State').textContent=reportState(release1);$('#release1Summary').innerHTML=summaryPairs(release1,[['automatic_gate_status','Gate automático'],['server_design_status','Server design'],['blocker_count','Blockers'],['runtime_game_acceptance_pending','Runtime/game pendente',v=>v?'SIM':'NÃO'],['production_authorized','Produção autorizada',v=>v?'SIM':'NÃO']]);$('#serverVendorPlanState').textContent=reportState(vendorPlan);$('#serverVendorPlanSummary').innerHTML=summaryPairs(vendorPlan,[['available_donor_count','Donors disponíveis'],['unavailable_donor_count','Donors ausentes'],['manifest','Manifest']]);$('#serverVendorGraphState').textContent=reportState(vendorGraph);$('#serverVendorGraphSummary').innerHTML=summaryPairs(vendorGraph,[['available_donor_count','Donors disponíveis'],['unavailable_donor_count','Donors ausentes'],['graph_dir','Pasta do grafo']]);if(design?.status)$('#serverRootStatus').textContent+=` · design ${design.status}`;await loadServerRows()}catch(e){$('#serverRootStatus').textContent='Erro';toast(e.message)}}
async function saveServerRoot(){const value=$('#serverRootInput').value.trim();try{const d=await api('/api/server/config',{method:'POST',body:{server_root:value}});S.boot.server_root=d.server_root;$('#settingsInfo').innerHTML=$('#settingsInfo').innerHTML.replace(/<dt>Server<\/dt><dd><code>.*?<\/code><\/dd>/,`<dt>Server</dt><dd><code>${esc(d.server_root||'não configurado')}</code></dd>`);toast(value?'Raiz do servidor salva':'Raiz do servidor removida');await loadServer()}catch(e){toast(e.message)}}
