async function loadGeneralCensus(){if(!$('#generalCensusRows'))return;const side=$('#generalCensusSide')?.value||'',decision=$('#generalCensusDecision')?.value||'',family=$('#generalCensusFamily')?.value||'',q=$('#generalCensusSearch')?.value.trim()||'';try{const qs=new URLSearchParams({side,decision,family,q,limit:'300'});const d=await api('/api/general-census?'+qs);const summary=d.summary||{};setCountOptions($('#generalCensusDecision'),summary.decision_counts||{},'Todas as decisões');setCountOptions($('#generalCensusFamily'),summary.physical_family_counts||{},'Todas as famílias');const freshness=d.freshness?` · ${d.freshness}`:'';$('#generalCensusCount').textContent=d.status==='NOT_RUN'?'Sem relatório. Execute Censo geral (plan-only).':`${Number(d.filtered_rows||0).toLocaleString()} de ${Number(d.total_rows||0).toLocaleString()} candidatos${freshness}`;const rows=d.rows||[];$('#generalCensusRows').innerHTML=rows.length?rows.map(row=>{const baseEv=row.reachability_evidence||row.review_evidence||row.manifest_evidence||row.source_evidence||row.reason||'—';const bundle=row.recovery_bundle_status?`Bundle ${row.recovery_bundle_status} · members ${row.recovery_bundle_member_count||0} · missing ${row.recovery_bundle_missing_count||0} · review ${row.recovery_bundle_review_count||0}`:'';const ev=bundle?`${bundle} · ${baseEv}`:baseEv;const strong=String(row.required_by_reachable_root).toLowerCase()==='true';return `<tr><td><span class="status-chip ${strong?'pass':'review'}">${esc(row.decision||'REVIEW')}</span></td><td>${esc(row.side||'—')}</td><td>${esc(row.physical_family||'—')}</td><td class=path title="${esc(row.path||'')}">${esc(row.path||'—')}</td><td title="${esc(ev)}">${esc(String(ev).slice(0,220))}</td></tr>`}).join(''):'<tr><td colspan="5" class="empty">Nenhum candidato corresponde aos filtros atuais.</td></tr>'}catch(e){$('#generalCensusRows').innerHTML=`<tr><td colspan="5" class="empty">${esc(e.message)}</td></tr>`;$('#generalCensusCount').textContent='Erro ao carregar censo geral'}}
async function saveContractRoots(){const source=$('#sourceRootInput').value.trim(),reference=$('#referenceSourceRootInput').value.trim(),donors=$('#contractDonorsInput').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),serverDonors=$('#contractServerDonorsInput')?$('#contractServerDonorsInput').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean):[];try{const d=await api('/api/contracts/config',{method:'POST',body:{source_root:source,reference_source_root:reference,donor_clients:donors,donor_servers:serverDonors}});S.boot.source_root=d.source_root;S.boot.reference_source_root=d.reference_source_root;S.boot.contract_donor_clients=d.donor_clients||[];S.boot.contract_donor_servers=d.donor_servers||[];toast('Fontes de Asset Contracts salvas');await loadContracts()}catch(e){toast(e.message)}}
async function pollContractJob(id){clearInterval(S.contractPoll);const poll=async()=>{try{const d=await api('/api/job?id='+encodeURIComponent(id)),j=d.job;$('#contractState').textContent=`${j.status} · ${j.action}`;if(['PASS','FAIL','ERROR','CANCELLED'].includes(j.status)){clearInterval(S.contractPoll);S.contractPoll=null;await loadContracts();toast(j.status==='PASS'?'Asset Contracts atualizados':`Asset Contracts: ${j.status}`)}}catch(e){clearInterval(S.contractPoll);S.contractPoll=null;toast(e.message)}};await poll();if(S.contractPoll===null&&/^(PASS|FAIL|ERROR|CANCELLED)/.test($('#contractState').textContent))return;S.contractPoll=setInterval(poll,1200)}
async function runContractAnalysis(mode){try{const d=await api('/api/contracts/analyze',{method:'POST',body:{mode}});S.job=d.job.id;$('#contractState').textContent=`QUEUED · contracts_${mode}`;const msg=mode==='source'?'Leitura de contratos do source iniciada':mode==='aggregate_player_classes'?'Agregação staging das 10 classes iniciada':mode==='aggregate_summit'?'Agregação completa Summit iniciada':mode==='general_census'?'Censo geral plan-only iniciado':'Audit das 10 classes iniciado';toast(msg);pollContractJob(d.job.id)}catch(e){toast(e.message)}}
async function pollServerJob(id){const poll=async()=>{try{const d=await api('/api/job?id='+encodeURIComponent(id)),j=d.job;$('#serverRootStatus').textContent=`${j.status} · ${j.action}`;if(['PASS','FAIL','ERROR','CANCELLED'].includes(j.status)){clearInterval(S.serverPoll);S.serverPoll=null;await loadServer();toast(j.status==='PASS'?'Análise server concluída':`Análise server: ${j.status}`)}}catch(e){clearInterval(S.serverPoll);S.serverPoll=null;toast(e.message)}};await poll();if(S.serverPoll==null&&$('#serverRootStatus').textContent.match(/^(PASS|FAIL|ERROR|CANCELLED)/))return;clearInterval(S.serverPoll);S.serverPoll=setInterval(poll,1200)}
async function runServerAnalysis(mode){try{const d=await api('/api/server/analyze',{method:'POST',body:{mode}});S.job=d.job.id;$('#serverRootStatus').textContent=`QUEUED · server_${mode}`;toast(`Análise server ${mode} iniciada`);pollServerJob(d.job.id)}catch(e){toast(e.message)}}
function compareOpenPath(report,row){const cr=S.boot?.client_root;if(report.left_root===cr&&row.left_path)return row.left_path;if(report.right_root===cr&&row.right_path)return row.right_path;return null}
function renderCompareReport(r){const s=r.summary||{},rows=(r.rows||[]),shown=rows.slice(0,500);$('#compareStatus').textContent=`PASS · ${Number(s.difference_path_count||0).toLocaleString()} diferenças`;const metrics=[['Esquerda',s.left_file_count],['Direita',s.right_file_count],['Só esquerda',s.only_left_count],['Só direita',s.only_right_count],['Diferentes',s.difference_path_count]];const table=shown.length?`<div class=compare-table><table><thead><tr><th>Status</th><th>Categoria</th><th>Ext</th><th>Path</th><th>Tamanho A</th><th>Tamanho B</th></tr></thead><tbody>${shown.map(row=>{const open=compareOpenPath(r,row);const path=row.left_path||row.right_path||row.key;return `<tr ${open?`data-open-asset="${esc(open)}" class=compare-row-clickable`:''}><td><span class="status ${esc(row.status)}">${esc(row.status)}</span></td><td>${esc(row.category||'—')}</td><td>${esc(row.extension||'—')}</td><td class=path title="${esc(path)}">${esc(path)}</td><td>${row.left_size==null?'—':fmtBytes(row.left_size)}</td><td>${row.right_size==null?'—':fmtBytes(row.right_size)}</td></tr>`}).join('')}</tbody></table></div>`:'<div class=empty>Nenhuma linha para exibir com os filtros atuais.</div>';$('#compareResult').innerHTML=`<div class=compare-summary>${metrics.map(([label,value])=>`<div class=metric><b>${Number(value||0).toLocaleString()}</b><span>${esc(label)}</span></div>`).join('')}</div><div class=compare-note>${r.content_hash?'SHA-256 ativo':'Comparação rápida por path/tamanho'} · ${r.differences_only?'somente diferenças':'todas as linhas'} · exibindo ${shown.length.toLocaleString()} de ${rows.length.toLocaleString()} linhas do relatório.</div>${table}`;$$('[data-open-asset]').forEach(x=>x.onclick=async()=>{setTab('catalog');await selectAsset(x.dataset.openAsset)})}
async function loadCompareReport(name){const d=await api('/api/report?name='+encodeURIComponent(name));renderCompareReport(d.report)}
async function pollTreeCompare(id,name){clearInterval(S.comparePoll);const poll=async()=>{try{const d=await api('/api/job?id='+encodeURIComponent(id)),j=d.job;$('#compareStatus').textContent=`${j.status} · ${j.action}`;if(j.status==='PASS'){clearInterval(S.comparePoll);S.comparePoll=null;await loadCompareReport(name);toast('Comparação concluída')}else if(['FAIL','ERROR','CANCELLED'].includes(j.status)){clearInterval(S.comparePoll);S.comparePoll=null;$('#compareResult').innerHTML=`<pre>${esc(j.tail||j.command_display)}</pre>`;toast(j.status==='CANCELLED'?'Comparação cancelada':'Comparação falhou')}}catch(e){clearInterval(S.comparePoll);S.comparePoll=null;$('#compareStatus').textContent='Erro ao consultar tarefa';toast(e.message)}};await poll();if(['PASS','FAIL','ERROR','CANCELLED'].some(x=>$('#compareStatus').textContent.startsWith(x)))return;S.comparePoll=setInterval(poll,1000)}
async function runTreeCompare(){const left=$('#compareLeft').value.trim(),right=$('#compareRight').value.trim();if(!left||!right){toast('Informe as duas árvores');return}try{const d=await api('/api/tree-compare',{method:'POST',body:{left,right,hash:$('#compareHash').checked,case_sensitive:$('#compareCase').checked,differences_only:$('#compareDiffOnly').checked,extensions:$('#compareExt').value.trim(),category:$('#compareCategory').value,path_contains:$('#comparePath').value.trim()}});S.job=d.job.id;S.compareOutput=String(d.output||'').split('/').pop();$('#compareStatus').textContent='QUEUED · tree_compare';$('#compareResult').innerHTML='<div class=empty>Comparação em andamento…</div>';toast('Comparação iniciada');pollTreeCompare(d.job.id,S.compareOutput)}catch(e){toast(e.message)}}
